create extension if not exists pgcrypto;
create table public.admin_users (user_id uuid primary key references auth.users on delete cascade);
create function public.is_admin() returns boolean language sql stable security definer set search_path = public as $$ select exists(select 1 from admin_users where user_id=auth.uid()) $$;
create table public.locations (id uuid primary key default gen_random_uuid(), country_code text not null default 'GB', country_name text not null default 'United Kingdom', region text, city text, neighbourhood text, postcode text, latitude numeric, longitude numeric, slug text unique);
create table public.organisation_types (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, description text);
create table public.venue_types (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, description text);
create table public.roles (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, description text);
create table public.relationship_types (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, description text);
create table public.emotion_families (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, description text);
create table public.genres (id uuid primary key default gen_random_uuid(), name text not null, slug text unique not null, parent_genre_id uuid references genres);
create table public.emotions (id uuid primary key default gen_random_uuid(), name text not null, slug text unique not null, family_id uuid references emotion_families);
create table public.entities (id uuid primary key default gen_random_uuid(), entity_type text not null check(entity_type in ('person','organisation','artist_project','venue')), display_name text not null check(length(trim(display_name)) between 1 and 200), slug text unique, description text, primary_location_id uuid references locations, visibility text not null default 'public' check(visibility in ('public','private')), verification_status text not null default 'unverified' check(verification_status in ('unverified','verified','potentially_outdated','disputed')), created_by uuid references auth.users on delete cascade, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), archived_at timestamptz);
create table public.people (entity_id uuid primary key references entities on delete cascade, first_name text, last_name text, preferred_name text);
create table public.organisations (entity_id uuid primary key references entities on delete cascade, organisation_type_id uuid references organisation_types, parent_organisation_id uuid references organisations(entity_id), website_domain text, scale text);
create table public.artist_projects (entity_id uuid primary key references entities on delete cascade, artist_type text not null, career_stage text, active boolean not null default true);
create table public.venues (entity_id uuid primary key references entities on delete cascade, venue_type_id uuid references venue_types, capacity_min integer check(capacity_min>=0), capacity_max integer check(capacity_max>=capacity_min), address_line_1 text, address_line_2 text, postcode text, layout_type text, age_restriction text, accessibility_notes text, green_room boolean, backline_available boolean, typical_artist_level text);
create table public.entity_roles (id uuid primary key default gen_random_uuid(), entity_id uuid not null references entities on delete cascade, role_id uuid not null references roles, organisation_id uuid references entities, started_at date, ended_at date, is_current boolean not null default true, unique(entity_id,role_id,organisation_id));
create table public.entity_relationships (id uuid primary key default gen_random_uuid(), source_entity_id uuid not null references entities on delete cascade, target_entity_id uuid not null references entities on delete cascade, relationship_type_id uuid not null references relationship_types, started_at date, ended_at date, is_current boolean not null default true, created_at timestamptz default now(), updated_at timestamptz default now(), check(source_entity_id<>target_entity_id), unique(source_entity_id,target_entity_id,relationship_type_id));
create table public.entity_locations (entity_id uuid references entities on delete cascade, location_id uuid references locations, relationship_type text not null default 'based_in', primary key(entity_id,location_id,relationship_type));
create table public.entity_genres (entity_id uuid references entities on delete cascade, genre_id uuid references genres, primary key(entity_id,genre_id));
create table public.entity_emotions (entity_id uuid references entities on delete cascade, emotion_id uuid references emotions, primary key(entity_id,emotion_id));
create table public.entity_contact_methods (id uuid primary key default gen_random_uuid(), entity_id uuid not null references entities on delete cascade, contact_type text not null, label text, value text not null, purpose text, is_primary boolean default false, is_public boolean not null default true, is_verified boolean default false, last_verified_at timestamptz, created_at timestamptz default now(), updated_at timestamptz default now(), unique(entity_id,id));
create table public.submission_channels (id uuid primary key default gen_random_uuid(), entity_id uuid not null references entities on delete cascade, submission_type text not null, status text not null default 'unknown' check(status in ('open','closed','unknown')), email_contact_method_id uuid, submission_url text, opens_at timestamptz, closes_at timestamptz, instructions text, fee_amount numeric check(fee_amount>=0), fee_currency text, last_verified_at timestamptz, foreign key(entity_id,email_contact_method_id) references entity_contact_methods(entity_id,id));
create table public.entity_aliases (id uuid primary key default gen_random_uuid(), entity_id uuid not null references entities on delete cascade, alias text not null, normalised_alias text not null, unique(entity_id,normalised_alias));
create table public.entity_sources (id uuid primary key default gen_random_uuid(), entity_id uuid not null references entities on delete cascade, source_type text, source_name text, source_url text, retrieved_at timestamptz default now(), verified_at timestamptz);
create table public.profiles (id uuid primary key references auth.users on delete cascade, display_name text, timezone text default 'Europe/London', country text, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.user_preferences (user_id uuid primary key references auth.users on delete cascade, primary_artist_entity_id uuid references entities on delete set null, goals jsonb not null default '[]', onboarding_completed boolean default false, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.user_contacts (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users on delete cascade default auth.uid(), entity_id uuid references entities on delete set null, private_display_name text, private_email text, private_details jsonb not null default '{}', relationship_status text not null default 'unknown' check(relationship_status in ('unknown','cold','contacted','warm','familiar','met_personally','worked_together','strong_relationship')), outreach_status text not null default 'not_contacted' check(outreach_status in ('not_contacted','draft','sent','replied','interested','declined','follow_up_needed','completed','no_response','do_not_contact')), priority text check(priority in ('low','medium','high')), relationship_origin text, first_contacted_at timestamptz, last_contacted_at timestamptz, follow_up_at date, archived boolean not null default false, created_at timestamptz default now(), updated_at timestamptz default now(), unique(user_id,entity_id), unique(user_id,id), check(entity_id is not null or length(trim(private_display_name))>0));
create table public.notes (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users on delete cascade default auth.uid(), user_contact_id uuid not null, body text not null check(length(trim(body)) between 1 and 20000), pinned boolean default false, created_at timestamptz default now(), updated_at timestamptz default now(), foreign key(user_id,user_contact_id) references user_contacts(user_id,id) on delete cascade);
create table public.interactions (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users on delete cascade default auth.uid(), user_contact_id uuid not null, type text not null, title text not null, metadata jsonb, occurred_at timestamptz default now(), created_at timestamptz default now(), foreign key(user_id,user_contact_id) references user_contacts(user_id,id) on delete cascade);
create table public.saved_views (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users on delete cascade default auth.uid(), name text not null, filter_definition jsonb not null default '{}', sort_definition jsonb default '{}', visible_columns jsonb default '[]', created_at timestamptz default now(), updated_at timestamptz default now());
create table public.lists (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users on delete cascade default auth.uid(), name text not null, created_at timestamptz default now(), unique(user_id,id));
create table public.list_members (user_id uuid not null references auth.users on delete cascade default auth.uid(), list_id uuid not null, user_contact_id uuid not null, primary key(list_id,user_contact_id), foreign key(user_id,list_id) references lists(user_id,id) on delete cascade, foreign key(user_id,user_contact_id) references user_contacts(user_id,id) on delete cascade);
create table public.email_templates (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users on delete cascade default auth.uid(), name text not null, category text, subject text not null, body text not null, created_at timestamptz default now(), updated_at timestamptz default now());
