create function public.contact_history() returns trigger language plpgsql security definer set search_path=public as $$ begin
 if TG_OP='INSERT' then insert into interactions(user_id,user_contact_id,type,title) values(new.user_id,new.id,'contact_added','Added to your network');
 else
 if new.relationship_status is distinct from old.relationship_status then insert into interactions(user_id,user_contact_id,type,title) values(new.user_id,new.id,'relationship_changed','Relationship: '||replace(new.relationship_status,'_',' ')); end if;
 if new.outreach_status is distinct from old.outreach_status then insert into interactions(user_id,user_contact_id,type,title) values(new.user_id,new.id,'outreach_status_changed','Outreach: '||replace(new.outreach_status,'_',' ')); end if;
 if new.follow_up_at is distinct from old.follow_up_at then insert into interactions(user_id,user_contact_id,type,title) values(new.user_id,new.id,'follow_up_changed','Follow-up updated'); end if;
 end if; return new; end $$;
create trigger contacts_history after insert or update on user_contacts for each row execute function contact_history();
create function public.note_history() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into interactions(user_id,user_contact_id,type,title) values(new.user_id,new.user_contact_id,'note_added','Private note added'); return new; end $$;
create trigger notes_history after insert on notes for each row execute function note_history();
create function public.complete_onboarding(project_name text, project_type text, city_name text, genre_names text[], emotion_names text[], user_goals jsonb) returns uuid language plpgsql security definer set search_path=public as $$
declare eid uuid; lid uuid; begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 if length(trim(project_name)) not between 1 and 200 or project_type not in ('solo','band','duo','collective','producer_project','dj_project','other') then raise exception 'Invalid artist'; end if;
 select primary_artist_entity_id into eid from user_preferences where user_id=auth.uid();
 select id into lid from locations where city=city_name limit 1;
 if eid is null then
 insert into entities(entity_type,display_name,visibility,created_by,primary_location_id) values('artist_project',trim(project_name),'private',auth.uid(),lid) returning id into eid;
 insert into artist_projects(entity_id,artist_type) values(eid,project_type);
 else
 if not exists(select 1 from entities where id=eid and created_by=auth.uid()) then raise exception 'Invalid owner'; end if;
 update entities set display_name=trim(project_name),primary_location_id=lid,updated_at=now() where id=eid;
 update artist_projects set artist_type=project_type where entity_id=eid;
 delete from entity_genres where entity_id=eid; delete from entity_emotions where entity_id=eid;
 end if;
 insert into entity_genres select eid,id from genres where name=any(genre_names);
 insert into entity_emotions select eid,id from emotions where name=any(emotion_names);
 insert into profiles(id,display_name) values(auth.uid(),project_name) on conflict(id) do update set display_name=excluded.display_name;
 insert into user_preferences(user_id,primary_artist_entity_id,goals,onboarding_completed) values(auth.uid(),eid,user_goals,true) on conflict(user_id) do update set goals=excluded.goals,onboarding_completed=true;
 return eid; end $$;
revoke all on function complete_onboarding(text,text,text,text[],text[],jsonb) from public;
grant execute on function complete_onboarding(text,text,text,text[],text[],jsonb) to authenticated;
